<template><q-page><div class="page-wrap"><PageHeader :title="config.title" :subtitle="config.subtitle" eyebrow="MARINA administration"><template #actions><q-btn outline color="primary" no-caps icon="download" label="Export CSV" @click="exportRows"/><q-btn v-if="!isAudit&&mode!=='roles'" unelevated color="primary" no-caps icon="add" :label="config.addLabel||'Add record'" @click="edit()"/></template></PageHeader>
<div v-if="mode==='users'" class="metric-grid"><div class="metric-card" v-for="s in ['active','invited','suspended']" :key="s"><div class="muted">{{s==='active'?'Active accounts':s==='invited'?'Issued invitations':'Suspended accounts'}}</div><div class="metric-value">{{store.state.users.filter(u=>u.status===s).length}}</div><div class="text-caption muted">MARINA-controlled access</div></div></div>
<div v-if="mode==='users'" class="help-note q-mb-lg">Invitations and recovery are simulated locally. Issuing an invitation does not send email. The activation screen accepts only an existing invited demo account.</div>
<div v-if="mode==='templates'" class="help-note q-mb-lg">Review, investigation and enforcement are separate lifecycles. Timing/requiredness settings below are proposed defaults; official templates and deadline rules require MARINA confirmation.</div>
<section class="panel"><div class="toolbar-row"><q-input v-model="search" outlined dense clearable debounce="150" placeholder="Search this register" style="min-width:260px"><template #prepend><q-icon name="search"/></template></q-input><q-select v-if="mode==='lookups'" v-model="category" :options="['All categories',...categories]" outlined dense label="Category" style="min-width:220px"/><q-select v-if="mode==='users'" v-model="accountStatus" :options="['All statuses','active','invited','suspended']" outlined dense label="Account status"/><q-space/><span class="text-caption muted">{{rows.length}} records</span></div>
<q-table flat :rows="rows" :columns="columns" row-key="id" :filter="search" :pagination="{rowsPerPage:10}" wrap-cells><template #body-cell-status="p"><q-td :props="p"><StatusBadge :status="p.value"/></q-td></template><template #body-cell-active="p"><q-td :props="p"><StatusBadge :status="p.value?'active':'inactive'"/></q-td></template><template #body-cell-actions="p"><q-td :props="p" class="text-right"><q-btn flat round dense :icon="isAudit?'visibility':'edit'" :aria-label="(isAudit?'View audit ':'Edit ')+(p.row.name||p.row.label||p.row.action)" @click="edit(p.row)"/><q-btn v-if="mode==='users'&&p.row.id!==user?.id" flat round dense :icon="p.row.status==='suspended'?'lock_open':'block'" :aria-label="p.row.status==='suspended'?'Reactivate account':'Suspend account'" @click="toggleAccount(p.row)"/></q-td></template><template #no-data><EmptyState title="No matching records" message="Adjust the search or add a record with your assigned permissions."/></template></q-table></section>
<div v-if="mode==='roles'" class="panel"><h3>Access scopes</h3><p class="muted">The three account types share operational tools for now. MARINA Investigator always has every function and all-office access; regional types cannot receive central system permissions.</p><div class="form-grid"><div v-for="scope in scopeDescriptions" :key="scope.name"><h4>{{scope.name}}</h4><p class="muted text-caption">{{scope.text}}</p></div></div><p class="help-note">This front-end permission preview is a handoff reference. Production must enforce the same rules at the API, including account suspension and session revocation.</p></div>
<div v-if="mode==='offices'" class="panel"><h3>Distinct office relationships</h3><div class="form-grid"><div v-for="n in ['Incident AOR','Vessel homeport office','CPC-issuing office','Actual SCO-issuing office']" :key="n"><q-icon name="account_balance" color="primary" class="q-mr-sm"/>{{n}}</div></div><p class="muted text-caption q-mt-lg">An office code is reusable across these roles; assigning one role does not overwrite another. No jurisdiction geometry is inferred from civil regions.</p></div>
<div v-if="mode==='templates'" class="content-grid"><div class="panel"><h3>Workflow states</h3><div v-for="flow in workflows" :key="flow.name" class="q-mb-lg"><h4>{{flow.name}}</h4><div class="row q-gutter-xs"><StatusBadge v-for="s in flow.states" :key="s" :status="s"/></div></div></div><div class="panel"><h3>Reminder policy</h3><q-input v-model="reminder" outlined type="number" min="0" label="Internal follow-up reminder (hours)" hint="A reminder setting, not a legal SCO compliance rule."/><q-btn class="q-mt-md" color="primary" outline no-caps label="Save reminder setting" @click="saveReminder"/></div></div>
</div><q-dialog v-model="dialog"><q-card class="wide-dialog"><q-card-section class="row items-center"><h3 class="q-mb-none">{{isAudit?'Audit entry':existingId?'Edit '+config.singular:config.addLabel}}</h3><q-space/><q-btn flat round dense icon="close" aria-label="Close editor" v-close-popup/></q-card-section><q-separator/><q-form @submit="save"><q-card-section><template v-if="isAudit"><div class="form-grid"><div v-for="k in ['actorName','action','recordId','at']" :key="k"><div class="text-caption muted">{{k}}</div><div>{{form[k]}}</div></div></div><pre class="audit-detail">{{prettyDetails}}</pre></template><div v-else class="form-grid"><template v-for="field in fields" :key="field.key"><q-select v-if="field.options" v-model="form[field.key]" :options="field.options" :disable="field.disabled" :multiple="field.multiple" :use-chips="field.multiple" :label="field.label" outlined :emit-value="field.emit" :map-options="field.emit" :class="{'span-2':field.wide}" :rules="field.required?[v=>!!v||'Required']:[]"/><q-toggle v-else-if="field.boolean" v-model="form[field.key]" :label="field.label"/><q-input v-else v-model="form[field.key]" outlined :label="field.label" :type="field.multiline?'textarea':field.type||'text'" :class="{'span-2':field.wide}" :rules="field.required?[v=>!!String(v||'').trim()||'Required']:[]" :hint="field.hint" :readonly="field.readonly"/></template></div><q-banner v-if="error" class="bg-red-1 text-negative q-mt-md" role="alert">{{error}}</q-banner></q-card-section><q-card-actions align="right"><q-btn flat no-caps label="Cancel" v-close-popup/><q-btn v-if="!isAudit&&mode!=='roles'" type="submit" color="primary" unelevated no-caps :label="mode==='users'&&!existingId?'Issue demo invitation':'Save changes'"/></q-card-actions></q-form></q-card></q-dialog></q-page></template>
<script setup>
import{computed,ref,reactive,watch}from'vue';import{useRoute}from'vue-router';import{useQuasar}from'quasar';import{useDemo}from'../stores/demo.js';import{clone,roleLabels,rolePermissions,operationalPermissions}from'../data/domain.js';import PageHeader from'../components/PageHeader.vue';import StatusBadge from'../components/StatusBadge.vue';import EmptyState from'../components/EmptyState.vue';import{downloadCSV}from'../lib/exports.js';
const store=useDemo(),route=useRoute(),$q=useQuasar(),user=computed(()=>store.currentUser.value),mode=computed(()=>route.meta.collection),search=ref(''),category=ref('All categories'),accountStatus=ref('All statuses'),dialog=ref(false),existingId=ref(null),form=reactive({}),error=ref(''),reminder=ref(store.state.settings.reminderHours||72);
const configs={users:{title:'Account management',subtitle:'Issue and manage approved reporting and staff accounts.',addLabel:'Issue account',singular:'account',columns:['name','email','role','officeId','scope','status']},roles:{title:'Roles & permissions',subtitle:'Assign resource actions and data scope independently of page visibility.',addLabel:'Add role',singular:'role',columns:['name','description','scope']},offices:{title:'MARINA offices',subtitle:'Maintain canonical codes and aliases for distinct office relationships.',addLabel:'Add office',singular:'office',columns:['code','name','aliases','active']},lookups:{title:'Reference data',subtitle:'Maintain controlled codes and source aliases used across forms, imports and reports.',addLabel:'Add value',singular:'reference value',columns:['category','code','label','aliases','active']},templates:{title:'Workflow & report templates',subtitle:'Version report layouts, requirements and operational reminders.',addLabel:'Add template',singular:'template',columns:['name','type','version','status']},auditLogs:{title:'Audit trail',subtitle:'Attributable demo actions, record changes and access events.',singular:'audit entry',columns:['at','actorName','action','recordId']}};
const config=computed(()=>configs[mode.value]||configs.auditLogs),isAudit=computed(()=>mode.value==='auditLogs');const rows=computed(()=>{let a=store.state[mode.value]||[];if(mode.value==='lookups'&&category.value!=='All categories')a=a.filter(x=>x.category===category.value);if(mode.value==='users'&&accountStatus.value!=='All statuses')a=a.filter(x=>x.status===accountStatus.value);return a}),categories=computed(()=>[...new Set(store.state.lookups.map(l=>l.category))]);
const labels={officeId:'Assigned office',actorName:'Actor',at:'Time (recorded)',recordId:'Record',active:'State'};const columns=computed(()=>[...config.value.columns.map(k=>({name:k,label:labels[k]||k.replace(/^./,c=>c.toUpperCase()),field:r=>k==='role'?roleLabels[r.role]:Array.isArray(r[k])?r[k].join(', '):r[k],align:'left',sortable:true})),{name:'actions',label:'',field:'id',align:'right'}]);
const select=(key,label,options,extra={})=>({key,label,options,...extra});const fields=computed(()=>{const offices=store.state.offices.map(o=>({label:o.code,value:o.id}));switch(mode.value){case'users':return[{key:'name',label:'Full name',required:true},{key:'email',label:'Issued email',type:'email',required:true},select('role','Assigned role',store.state.roles.map(r=>({label:r.name,value:r.id})),{emit:true,required:true}),select('officeId','Assigned office',offices,{emit:true,required:true}),select('scope','Record scope',['own','office','all']),select('status','Account state',['invited','active','suspended']),{key:'organization',label:'Organization',wide:true}];case'roles':return[{key:'name',label:'Role name',required:true,readonly:true},{key:'description',label:'Description'},select('scope','Default record scope',['own','office','all'],{disabled:existingId.value==='investigator'}),select('permissions','Permitted actions',existingId.value==='investigator'?rolePermissions.investigator:operationalPermissions,{multiple:true,wide:true,disabled:existingId.value==='investigator'})];case'offices':return[{key:'code',label:'Canonical office code',required:true},{key:'name',label:'Office name',required:true},{key:'aliasText',label:'Source aliases',hint:'Separate aliases with commas.',wide:true},{key:'active',label:'Active',boolean:true}];case'lookups':return[{key:'category',label:'Category',required:true},{key:'code',label:'Stable code',required:true},{key:'label',label:'Display label',required:true},{key:'aliasText',label:'Source aliases',hint:'Separate aliases with commas.'},{key:'active',label:'Active',boolean:true}];case'templates':return[{key:'name',label:'Template name',required:true},select('type','Report type',['spot','1A','1B','2','3B','Master list']),{key:'version',label:'Version',required:true},select('status','Template state',['Draft reference','Source required','Approved reference']),{key:'requiredText',label:'Required sections',hint:'Separate names with commas.',wide:true},{key:'notes',label:'Template notes',multiline:true,wide:true}];default:return[]}});
function edit(row){existingId.value=row?.id||null;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,row?clone(row):{status:mode.value==='users'?'invited':'Draft reference',role:'reporter',scope:'own',officeId:'MRO-IV',active:true,permissions:['read'],version:'Draft 1',type:'spot'});form.aliasText=(form.aliases||[]).join(', ');form.requiredText=(form.requiredFields||[]).join(', ');error.value='';dialog.value=true;}
function save(){try{const d=clone(form);if(['offices','lookups'].includes(mode.value))d.aliases=String(d.aliasText||'').split(',').map(v=>v.trim()).filter(Boolean);if(mode.value==='templates')d.requiredFields=String(d.requiredText||'').split(',').map(v=>v.trim()).filter(Boolean);delete d.aliasText;delete d.requiredText;if(mode.value==='users'){if(d.role==='investigator')d.scope='all';if(store.state.users.some(u=>u.email.toLowerCase()===String(d.email).toLowerCase()&&u.id!==existingId.value))throw Error('An issued account already uses this email.');if(d.id===user.value.id&&d.status!=='active')throw Error('Use another authorized MARINA Investigator to suspend this account.');}if(existingId.value)store.update(mode.value,existingId.value,d);else store.add(mode.value,d);dialog.value=false;$q.notify({type:'positive',message:mode.value==='users'&&!existingId.value?'Demo invitation issued. No email sent.':'Changes saved in the demonstration.'})}catch(e){error.value=e.message}}
function toggleAccount(row){const next=row.status==='suspended'?'active':'suspended';$q.dialog({title:next==='active'?'Reactivate account?':'Suspend account?',message:`${row.name} (${row.email}) will be ${next}. Historical submissions remain attributed to this account.`,cancel:true,persistent:true}).onOk(()=>{try{store.update('users',row.id,{status:next});$q.notify({type:'positive',message:'Account state updated.'})}catch(e){$q.notify({type:'negative',message:e.message})}})}
function exportRows(){downloadCSV('saferseas-'+mode.value+'.csv',rows.value.map(r=>Object.fromEntries(config.value.columns.map(k=>[k,Array.isArray(r[k])?r[k].join('; '):r[k]]))));store.audit('Exported '+mode.value,mode.value,`${rows.value.length} demo rows`)}
const prettyDetails=computed(()=>{try{return JSON.stringify(JSON.parse(form.details),null,2)}catch{return form.details}});const scopeDescriptions=[{name:'Own',text:'Only records attributed to the issued account.'},{name:'Office',text:'Records attributed to or assigned to the account’s office.'},{name:'All',text:'All records within the granted resource/action permissions.'}];const workflows=[{name:'Data review',states:['draft','submitted','under_review','correction_requested','resubmitted','validated']},{name:'Investigation report',states:['draft','review','issued']},{name:'Enforcement case',states:['ongoing_sco','ongoing_penalty','dismissed','closed']}];function saveReminder(){store.state.settings.reminderHours=Number(reminder.value);store.audit('Updated reminder policy','settings',`${reminder.value} hours; proposed internal setting`);$q.notify({type:'positive',message:'Reminder setting saved; no legal timeliness rule inferred.'})}watch(()=>form.role,(value,previous)=>{if(dialog.value&&!existingId.value&&value!==previous)form.scope=value==='investigator'?'all':value==='reviewer'?'office':'own'});watch(mode,()=>{search.value='';dialog.value=false;category.value='All categories';accountStatus.value='All statuses'});
</script><style scoped>.audit-detail{white-space:pre-wrap;overflow-wrap:anywhere;max-width:100%;font-size:12px;background:var(--ss-bg);padding:15px;border-radius:9px;margin-top:20px}</style>
